import os
import re
import sys

import pytest

from click import Command
from click import option
from click.shell_completion import CompletionItem
from click.shell_completion import FishComplete
from click.testing import CliRunner


@pytest.fixture
def runner():
    return CliRunner()


@pytest.fixture
def prog_name():
    return "test-cli"


@pytest.fixture
def complete_var():
    return "_TEST_CLI_COMPLETE"


@pytest.fixture
def make_completion_context(prog_name, complete_var):
    def _make_completion_context(cli, args, incomplete):
        comp = FishComplete(cli, {}, prog_name, complete_var)
        os.environ["COMP_WORDS"] = " ".join(args)
        os.environ["COMP_CWORD"] = str(len(args) - 1)
        os.environ["_CLICK_COMPLETE_FISH_INCOMPLETE"] = incomplete
        return comp

    return _make_completion_context


def test_fish_completion_multiline_help(
    runner, make_completion_context, prog_name, complete_var
):
    @option(
        "--at",
        help="\b\nAttachment with explicit mimetype,\n--at image.jpg image/jpeg",
    )
    def cli(at):
        pass

    cmd = Command("cli", callback=cli)
    comp = make_completion_context(cmd, [prog_name, "--"], "")
    result = comp.complete()

    # The expected output should have the multiline help text on a single line,
    # with newlines replaced by spaces, and the leading \b removed.
    expected_completion = (
        "plain,--at\tAttachment with explicit mimetype, --at image.jpg image/jpeg"
    )
    assert expected_completion in result
